/**
 * Utility to parse, extract, and format citations generated by PaperMind RAG backend.
 *
 * Typical backend citations:
 * - [filename.pdf, Page 3, Section: Model Architecture]
 * - [filename.pdf, Page 5]
 * - [Page 2]
 */

export function extractCitations(text, defaultSource = '') {
  if (!text || typeof text !== 'string') return [];

  // Regex to match citations like:
  // [something.pdf, Page 3, Section: Heading]
  // [something.pdf, Page 3]
  // [Page 3]
  const regex = /\[(?:([^,\]]+),\s*)?Page\s+(\d+)(?:,\s*Section:\s*([^\]]+))?\]/gi;
  const matches = [];
  const citationMap = new Map();

  let match;
  let index = 0;

  while ((match = regex.exec(text)) !== null) {
    const raw = match[0];
    const source = (match[1] || defaultSource || 'Reference Document').trim();
    const page = match[2].trim();
    const section = match[3] ? match[3].trim() : null;

    const key = `${source}_p${page}_${section || 'nosection'}`;

    if (citationMap.has(key)) {
      const existing = citationMap.get(key);
      existing.occurrences += 1;
      existing.indices.push(match.index);
    } else {
      const cit = {
        id: `cit-${index++}`,
        raw,
        source,
        page: parseInt(page, 10),
        section,
        occurrences: 1,
        indices: [match.index],
      };
      citationMap.set(key, cit);
      matches.push(cit);
    }
  }

  return matches;
}

/**
 * Format citation label for compact display badges
 */
export function formatCitationBadge(cit) {
  let label = `p. ${cit.page}`;
  if (cit.section) {
    label += ` · ${cit.section}`;
  }
  return label;
}
